<script setup>
import { computed, onMounted, reactive, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ElMessage } from 'element-plus'
import EChart from '../../components/EChart.vue'
import { getBills } from '../../api/bill.js'
import { getMonthlyCommunities, getMonthlyDrilldown, getMonthlyStatistics } from '../../api/statistics.js'
import { apiMessage } from '../../api/http.js'

const route = useRoute(), router = useRouter(), year = ref(2026), month = ref(null), communityId = ref(null)
const rows = ref([]), communities = ref([]), detail = ref(null), bills = ref([]), billTotal = ref(0), loading = ref(false)
const billQuery = reactive({ page: 1, pageSize: 20 })
const money = value => new Intl.NumberFormat('zh-CN', { minimumFractionDigits: 2 }).format(value || 0)
const option = computed(() => ({ tooltip: { trigger: 'axis' }, legend: { data: ['应收', '实收', '收缴率'] }, xAxis: { type: 'category', data: rows.value.map(x => `${x.month}月`) }, yAxis: [{ type: 'value' }, { type: 'value', axisLabel: { formatter: '{value}%' } }], series: [{ name: '应收', type: 'bar', data: rows.value.map(x => x.receivableAmount), itemStyle: { color: '#6ab1a8' } }, { name: '实收', type: 'bar', data: rows.value.map(x => x.receivedAmount), itemStyle: { color: '#167d72' } }, { name: '收缴率', type: 'line', yAxisIndex: 1, data: rows.value.map(x => x.collectionRatePercent), itemStyle: { color: '#c9933b' } }] }))
function syncQuery() { year.value = Number(route.query.year) || 2026; month.value = route.query.month ? Number(route.query.month) : null; communityId.value = route.query.communityId ? Number(route.query.communityId) : null }
async function loadDetail() { if (!month.value) { detail.value = null; communities.value = []; bills.value = []; return } const [nextDetail, nextCommunities] = await Promise.all([getMonthlyDrilldown(year.value, month.value, communityId.value), getMonthlyCommunities(year.value, month.value)]); detail.value = nextDetail; communities.value = nextCommunities; if (communityId.value) { const page = await getBills({ year: year.value, month: month.value, communityId: communityId.value, page: billQuery.page, pageSize: billQuery.pageSize }); bills.value = page.records; billTotal.value = page.total } else { bills.value = []; billTotal.value = 0 } }
async function load() { loading.value = true; try { syncQuery(); rows.value = await getMonthlyStatistics(year.value); await loadDetail() } catch (e) { ElMessage.error(apiMessage(e, '月度统计加载失败')) } finally { loading.value = false } }
function selectMonth(row) { router.push({ name: 'monthly-statistics', query: { year: year.value, month: row.month } }) }
function selectCommunity(row) { router.push({ name: 'monthly-statistics', query: { year: year.value, month: month.value, communityId: row.communityId } }) }
function backToYear() { router.push({ name: 'annual-statistics', query: { year: year.value } }) }
watch(() => route.fullPath, load)
onMounted(load)
</script>
<template><section v-loading="loading"><div class="toolbar"><div><p class="muted">点击月份进入该月总览；再点击小区查看账单明细。</p><el-button v-if="month" link type="primary" @click="backToYear">返回年度统计</el-button></div><el-select v-model="year" style="width:110px" @change="router.push({name:'monthly-statistics',query:{year}})"><el-option :value="2026" label="2026 年"/></el-select></div><section class="panel chart"><EChart :option="option" height="360px"/></section><section class="panel table"><h2>月份总览</h2><el-table :data="rows" @row-click="selectMonth"><el-table-column label="月份"><template #default="{row}">{{row.month}} 月</template></el-table-column><el-table-column prop="billCount" label="账单数"/><el-table-column label="应收"><template #default="{row}">¥ {{money(row.receivableAmount)}}</template></el-table-column><el-table-column label="实收"><template #default="{row}">¥ {{money(row.receivedAmount)}}</template></el-table-column><el-table-column label="欠费"><template #default="{row}">¥ {{money(row.outstandingAmount)}}</template></el-table-column><el-table-column label="收缴率"><template #default="{row}">{{Number(row.collectionRatePercent).toFixed(2)}}%</template></el-table-column><el-table-column label="下钻"><template #default="{row}"><el-button link type="primary" @click.stop="selectMonth(row)">查看小区</el-button></template></el-table-column></el-table></section><template v-if="detail"><section class="drill-title"><p class="eyebrow">MONTHLY DRILL-DOWN</p><h2>{{detail.year}} 年 {{detail.month}} 月 · {{detail.communityName}}</h2></section><div class="kpis"><article v-for="[label,value,kind] in [['应收',detail.receivableAmount,'money'],['实收',detail.receivedAmount,'money'],['欠费',detail.outstandingAmount,'money'],['收缴率',detail.collectionRatePercent,'percent'],['账单数',detail.billCount,'number']]" :key="label" class="panel"><span>{{label}}</span><b>{{kind==='money'?'¥ '+money(value):kind==='percent'?Number(value||0).toFixed(2)+'%':value||0}}</b></article></div><div class="double"><section class="panel table"><h2>费用组成</h2><el-table :data="detail.feeComposition"><el-table-column prop="feeName" label="收费项目"/><el-table-column label="应收"><template #default="{row}">¥ {{money(row.receivableAmount)}}</template></el-table-column></el-table></section><section class="panel table"><h2>账单状态</h2><el-table :data="detail.billStatusDistribution"><el-table-column prop="status" label="状态"/><el-table-column prop="billCount" label="账单数"/></el-table></section></div><section v-if="!communityId" class="panel table"><h2>该月全部小区</h2><el-table :data="communities" @row-click="selectCommunity"><el-table-column prop="communityName" label="小区"/><el-table-column prop="billCount" label="账单数"/><el-table-column label="应收"><template #default="{row}">¥ {{money(row.receivableAmount)}}</template></el-table-column><el-table-column label="实收"><template #default="{row}">¥ {{money(row.receivedAmount)}}</template></el-table-column><el-table-column label="欠费"><template #default="{row}">¥ {{money(row.outstandingAmount)}}</template></el-table-column><el-table-column label="收缴率"><template #default="{row}">{{Number(row.collectionRatePercent).toFixed(2)}}%</template></el-table-column><el-table-column label="下钻"><template #default="{row}"><el-button link type="primary" @click.stop="selectCommunity(row)">查看明细</el-button></template></el-table-column></el-table></section><section v-else class="panel table"><h2>该小区账单明细</h2><el-table :data="bills"><el-table-column prop="billNo" label="账单号"/><el-table-column prop="propertyNo" label="房产"/><el-table-column label="应收"><template #default="{row}">¥ {{money(row.receivableAmount)}}</template></el-table-column><el-table-column label="实收"><template #default="{row}">¥ {{money(row.receivedAmount)}}</template></el-table-column><el-table-column label="欠费"><template #default="{row}">¥ {{money(row.outstandingAmount)}}</template></el-table-column><el-table-column prop="status" label="状态"/></el-table><el-pagination v-model:current-page="billQuery.page" :total="billTotal" layout="prev,pager,next" @current-change="loadDetail"/></section></template></section></template>
<style scoped>.toolbar{display:flex;justify-content:space-between;align-items:center;margin-bottom:16px}.chart,.table{padding:20px}.table{margin-top:17px}.table h2{margin:0 0 13px;font-size:17px}.drill-title{margin:31px 0 14px}.drill-title .eyebrow{margin:0 0 5px}.drill-title h2{margin:0;color:#153c4b;font:500 26px/1.2 Georgia,'Noto Serif SC',serif}.kpis{display:grid;grid-template-columns:repeat(5,1fr);gap:14px;margin-bottom:17px}.kpis article{padding:18px}.kpis span{display:block;color:#718692;font-size:12px}.kpis b{display:block;margin-top:10px;color:#14394a;font-size:20px}.double{display:grid;grid-template-columns:1fr 1fr;gap:17px}.double .table{margin-top:0}@media(max-width:1200px){.kpis{grid-template-columns:repeat(3,1fr)}.double{grid-template-columns:1fr}}</style>
